      mc('Perché le mosse forzanti sono utili al calcolo?', ['Riducono le risposte dell’avversario', 'Valgono più punti', 'Sono sempre vincenti', 'Sono sempre legali'], 0, 'Con meno risposte l’albero delle varianti è più piccolo.'),
      mc('Dove ci si ferma durante il calcolo di una variante?', ['In una posizione tranquilla, senza scacchi o catture in sospeso', 'Dopo una mossa', 'Quando si è stanchi', 'Dopo la prima cattura'], 0, 'Solo così si può valutare la posizione.'),
      fill('Nella posizione guidata, quale mossa del Bianco è la migliore? Scrivi la mossa (Alfiere prende il Cavallo).', ['Axf6', 'Axf6!'], 'Axf6 elimina il difensore di h7.'),
      mc('Perché nella posizione guidata 1.Dxh7+ non funziona?', ['Perché Cxh7 cattura la Donna', 'Perché è illegale', 'Perché la Torre nera la cattura', 'Perché non è scacco'], 0, 'Il Cavallo f6 difende h7 e cattura la Donna.'),
      mc('Quali sono i quattro criteri di valutazione?', ['Materiale, sicurezza del Re, attività dei pezzi, struttura dei pedoni', 'Colore, forma, peso, lunghezza', 'Tempo, mosse, nome, punteggio', 'Apertura, mediogioco, finale, patta'], 0, 'Sono i criteri base per valutare una posizione.'),
      mc('Che cosa significa il controllo anti-errore?', ['Verificare che la mossa non lasci pezzi in presa né permetta tattiche', 'Chiedere un parere esterno', 'Riscrivere la partita', 'Ripetere la mossa'], 0, 'Si controlla dove va il pezzo, che cosa lascia e le minacce avversarie.'),
      mc('Hai calcolato bene una variante vincente e il controllo anti-errore torna. Che cosa fai?', ['Giochi con decisione', 'Calcoli per altri venti minuti', 'Cambi mossa', 'Offri patta'], 0, 'Dubitare di un buon calcolo fa solo perdere tempo.'),
      order('Ordina i passi del metodo.', ['Guarda', 'elenca le candidate', 'calcola le forzanti', 'valuta', 'controlla gli errori', 'muovi'], 'È il metodo in sei passi.')
